translator = Translator()

# Start komandasi va tugmalar
async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    keyboard = [
        [InlineKeyboardButton("🌏ENGLISH", callback_data='english🌏')],
        [InlineKeyboardButton("🌏UZBEK", callback_data='uzbek🌏')],
        [InlineKeyboardButton("🌏About My Professional Hub Bot🌏", callback_data='about')],
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    await update.message.reply_text('😍Iltimos, tilni tanlang:😍', reply_markup=reply_markup)

# Tugma bosilganda bo'ladigan ish
async def button(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    choice = query.data
    if choice == "english":
        await query.edit_message_text(text="Assalomu Aleykum! Bizning botimizga xush kelibsiz. Iltimos, inglizcha so'zni kiriting.")
        context.user_data['language'] = 'english'  # Foydalanuvchining tanlovini saqlaymiz
    elif choice == "uzbek":
        await query.edit_message_text(text="Assalomu Aleykum! Bizning botimizga xush kelibsiz. Biz harqanda inglizcha so'zni uzbek tilidagi tarjimasini topib beramiz.")
        context.user_data['language'] = 'uzbek'  # Foydalanuvchining tanlovini saqlaymiz
    elif choice == "about":
        await query.edit_message_text(text="""My Professional Hub Bot - Bu bot inglizcha va o'zbekcha tarjimalar bilan foydalanuvchilarga yordam beradi. "
                                           
                                              "Haqiqiy vaqt rejimida tarjimalar va foydalanuvchi interaktivligi.
                                           
                                           My Professional Hub loyihasi asoschisi Suyunova Saygul ✅  
                                           telegram: @saygul0901 📧
                                      
                                           @My_Professional_Hub_bot 🤖 bot yaratuvchisi Ergashev Anvar 
                                             telegram: @Mr_Anvar_7500 📧 
                                      
                                           """)
    
# So'zni tarjima qilish
async def translate_word(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_input = update.message.text.strip().lower()
    language = context.user_data.get('language')

    if language == 'english':
        # Inglizcha so'zni O'zbekchaga tarjima qilish
        translation = english_to_uzbek.get(user_input)
        if translation:
            await update.message.reply_text(f"{user_input} = {translation}")
        else:
            # Xato so'z kiritsangiz
            await update.message.reply_text(f"❌ Xato so'z kiritildi. Iltimos qayta urinib ko'ring. Masalan: 'hello' yoki 'world'.")
            # Agar so'z topilmasa, Google Translate bilan tarjima qilamiz
            # translation = await translator.translate(user_input, src='en', dest='uz')  # await qo'shildi
            # await update.message.reply_text(f"{user_input} = {translation.text}")
    elif language == 'uzbek':
        # O'zbekcha so'zni Inglizchaga tarjima qilish
        translation = {v: k for k, v in english_to_uzbek.items()}.get(user_input)
        if translation:
            await update.message.reply_text(f"{user_input} = {translation}")
        else:
            # Xato so'z kiritsangiz
            await update.message.reply_text(f"❌ Xato so'z kiritildi. Iltimos qayta urinib ko'ring. Masalan: 'salom' yoki 'olam'.")
            # Agar so'z topilmasa, Google Translate bilan tarjima qilamiz
            # translation = await translator.translate(user_input, src='uz', dest='en')  # await qo'shildi
            # await update.message.reply_text(f"{user_input} = {translation.text}")

# Botni ishga tushirish
def main():
    TOKEN = '7637742776:AAHs8ZmmOEWCr0h2Dc-cyIe2YArldRHq0bE'  # @BotFather'dan olgan tokenni qo'ying
    application = Application.builder().token(TOKEN).build()

    application.add_handler(CommandHandler('start', start))  # Start komandasi
    application.add_handler(CallbackQueryHandler(button))   # Tugma bosish
    application.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, translate_word))  # So'zni tarjima qilish

    application.run_polling()  # Botni ishga tushirish

if __name__ == '__main__':
    main()
